INSERT INTO `changelogs` VALUES (1,'2026-06-04','09:00:00','Versi 0.2 â€” Initial Release','Peluncuran awal Garuda Nexa Dashboard v0.2','fitur','2026-06-04 14:50:47'),(2,'2026-06-04','09:30:00','Fitur Pencarian Produk Dihapus','Hapus search bar & logic filter produk di halaman List Product. Gunakan grid display langsung.','hapus','2026-06-04 14:50:47'),(3,'2026-06-04','10:00:00','Toast Copy â€” Pindah ke Atas & Animasi','Notifikasi copy username/password pindah dari bawah (bottom-8) ke atas (top-6). Tambah animasi fade-in dari atas. Z-index paling depan (z-[9999]).','fitur','2026-06-04 14:50:47'),(4,'2026-06-04','10:20:00','Modal Detail â€” Layout 2 Kolom','Restruktur modal jadi 2 kolom: kiri (40%) logo + judul + deskripsi + button + credentials, kanan (60%) catatan. Catatan punya min-h-[200px].','fitur','2026-06-04 14:50:47'),(5,'2026-06-04','10:45:00','Modal Detail â€” Logo & Button Rata Kiri','Logo, judul, deskripsi, button Kunjungi Website diubah dari center ke left-aligned.','ui','2026-06-04 14:50:47'),(6,'2026-06-04','11:00:00','Button Close â€” Lebih Pojok & Kecil','Tombol X pindah dari top-6 right-6 ke top-3 right-3. Padding p-2 ke p-1.5, icon w-5 ke w-4.','ui','2026-06-04 14:50:47'),(7,'2026-06-04','11:10:00','Button Kunjungi Website â€” Lebih Kecil','Ukuran button: px-5 py-2.5 ke px-3.5 py-2. Text sm ke xs.','ui','2026-06-04 14:50:47'),(8,'2026-06-04','11:30:00','Modal â€” Lebar Max & Gap Rapat','Lebar modal max-w-2xl ke max-w-3xl. Padding p-6 ke p-8. Jarak logo-judul-deskripsi-button dikurangi.','fitur','2026-06-04 14:50:47'),(9,'2026-06-04','12:00:00','Sistem Catatan Perubahan Interaktif','Implementasi sistem changelog berbasis database menggantikan static content.','fitur','2026-06-04 15:30:36'),(10,'2026-06-04','12:15:00','Kalender & Navigasi Tanggal','Fitur kalender interaktif untuk memilih tanggal, navigasi bulan, dan tahun.','ui','2026-06-04 15:30:36'),(11,'2026-06-04','12:30:00','Form Tambah Data (Database)','Penambahan form untuk input catatan perubahan langsung dari dashboard ke MySQL.','fitur','2026-06-04 15:30:36'),(12,'2026-06-04','12:45:00','Logo Biru & Responsive Mobile','Logo Garuda Nexa diubah ke warna biru via CSS filter dan ukuran diperkecil untuk tampilan mobile.','ui','2026-06-04 15:30:36'),(13,'2026-06-04','13:00:00','Halaman Catatan Perubahan - Dark/Light Mode','Semua card, text, dan input form di halaman changelog otomatis menyesuaikan tema dark dan light.','ui','2026-06-04 15:42:15'),(14,'2026-06-04','13:15:00','API Backend - CRUD Changelogs','Penambahan endpoint API: get_changelogs (filter by date/month), add_changelog (auto time), delete_changelog.','fitur','2026-06-04 15:42:15'),(15,'2026-06-04','13:30:00','Changelogs Table MySQL','Pembuatan tabel changelogs dengan index tanggal untuk performa query.','fitur','2026-06-04 15:42:15'),(16,'2026-06-04','13:45:00','Build Fix - TypeScript Error','Perbaikan error tipe data unknown[] pada datesWithChanges state.','fitur','2026-06-04 15:42:15'),(17,'2026-06-04','14:00:00','Logo Responsive - Modal ListProduct','Logo di modal detail produk diperkecil di mobile (h-16 ke h-10 md:h-16).','ui','2026-06-04 15:42:15'),(18,'2026-06-04','14:15:00','Data Seed - 12 Catatan Perubahan','Pengisian semua catatan perubahan dari sesi hari ini ke database.','fitur','2026-06-04 15:42:15'),(20,'2024-11-20','10:00:00','Test via curl','Test aja','fitur','2026-06-06 11:09:10'),(22,'2026-06-06','18:16:00','COBA','COBA 2','fitur','2026-06-06 11:16:12'),(23,'2026-06-05','18:26:00','Update ','Fitur pada menghilang','fitur','2026-06-06 11:27:14'),(25,'2026-06-07','01:23:00','I-School','Update I-School Statistik','fitur','2026-06-06 18:23:50'),(26,'2026-06-07','14:30:00','Halaman Changelog Admin','Menambahkan halaman Changelog di panel admin dengan fitur CRUD lengkap (Tambah, Edit, Hapus) dan tampilan timeline.','fitur','2026-06-07 16:29:23'),(27,'2026-06-06','10:15:00','Perbaikan Order Produk','Memperbaiki bug urutan produk tidak tersimpan saat drag-and-drop di halaman List Product.','perbaikan','2026-06-07 16:29:23'),(28,'2026-06-05','09:00:00','Optimasi Mobile Responsive','Menyesuaikan typography Hero section dan ikon navbar untuk tampilan mobile yang lebih rapi.','peningkatan','2026-06-07 16:29:23');
