INSERT INTO `hero_settings` VALUES (1,'hero_title','Leading With Vision, Moving With Purpose','2026-06-03 11:52:12'),(2,'hero_subtitle','We don\'t just build apps and websites. We build digital systems that help your business and institution grow faster, more efficiently, and more professionally.','2026-06-03 11:53:09'),(3,'contact_email','info@garudanexa.com','2026-06-03 10:49:59'),(4,'contact_whatsapp','628123456789','2026-06-03 10:49:59'),(5,'site_logo','/assets/logo/logogarudanexa.png','2026-06-03 10:49:59'),(6,'hero_logos','[]','2026-06-03 10:49:59'),(13,'hero_badge','Jasa Pembuatan Aplikasi & Website','2026-06-04 08:33:22'),(14,'hero_primary_btn','Lihat Produk Kami','2026-06-03 11:52:12'),(15,'hero_secondary_btn','Hubungi Kami','2026-06-03 11:52:12'),(16,'hero_images','[\"/assets/bg/hero_1780591345858_ig6055_0.jpg\",\"/assets/bg/hero_1780591345859_gvjt1h_1.jpg\",\"/assets/bg/hero_1780591345859_8h5xf9_2.jpg\",\"/assets/bg/hero_1780591345860_f0789h_3.jpg\",\"/assets/bg/hero_1780591345860_cykxto_4.jpg\",\"/assets/bg/hero_1780591345860_5020eq_5.jpg\",\"/assets/bg/hero_1780591345861_vociaw_7.jpg\"]','2026-06-06 21:12:39'),(47,'products_categories','[{\"id\":\"all\",\"label\":\"Semua\"},{\"id\":\"website\",\"label\":\"Website\"},{\"id\":\"santri\",\"label\":\"I-Santri\"},{\"id\":\"school\",\"label\":\"I-School\"},{\"id\":\"pos\",\"label\":\"POS\"},{\"id\":\"absensi\",\"label\":\"Absensi\"},{\"id\":\"invitation\",\"label\":\"Undangan Digital\"}]','2026-06-04 07:46:45'),(48,'products_data','[{\"id\":\"website\",\"category\":\"website\",\"badge\":\"Jasa Pembuatan Website\",\"title\":\"Profil Perusahaan & Web Kustom\",\"description\":\"Website sekolah/instansi, Landing Page Produk, dan Website Custom System.\",\"image\":\"/assets/portofolio/portfolio1.png\"},{\"id\":\"santri\",\"category\":\"santri\",\"logo\":\"/assets/logo/logoisantri.png\",\"badge\":\"Aplikasi I-Santri\",\"title\":\"Manajemen Pesantren Modern\",\"description\":\"Manajemen pesantren yang lebih terstruktur dan modern dengan sistem digital terintegrasi.\",\"image\":\"/assets/product/isantri.png\"},{\"buttonText\":\"Pesan Sekarang\",\"buttonLink\":\"https://office.ischool.my.id\",\"id\":\"school\",\"category\":\"school\",\"logo\":\"/assets/logo/logoischool.png\",\"badge\":\"Aplikasi I-School\",\"title\":\"Digitalisasi Ekosistem Sekolah\",\"description\":\"Manajemen sekolah berbasis digital tingkat lanjut untuk efisiensi administrasi dan akademik.\",\"image\":\"/assets/product/ischool.png\"},{\"id\":\"pos\",\"category\":\"pos\",\"badge\":\"Aplikasi Kasir\",\"title\":\"Sistem POS Cerdas untuk UMKM\",\"description\":\"Sistem Point of Sale (POS) yang memudahkan transaksi dan manajemen stok untuk UMKM & retail.\",\"image\":\"/assets/product/pos.png\"},{\"buttonText\":\"Pesan Sekarang\",\"buttonLink\":\"\",\"id\":\"absensi\",\"category\":\"absensi\",\"badge\":\"Aplikasi Absensi\",\"title\":\"Kehadiran Digital Real-time\",\"description\":\"Sistem absensi digital berbasis web dan mobile dengan verifikasi yang akurat dan aman.\",\"image\":\"data:image/jpeg;base64,\"},{\"id\":\"invitation\",\"category\":\"invitation\",\"logo\":\"/assets/logo/logowedding.png\",\"badge\":\"Undangan Digital Premium\",\"title\":\"Undangan Digital Interaktif\",\"description\":\"Solusi undangan pernikahan dan acara spesial dalam bentuk website modern yang elegan dan mudah dibagikan.\",\"image\":\"/assets/product/undangan_digital.png\"}]','2026-06-06 21:22:48'),(49,'portfolio_data','[{\"title\":\"Web App Dashboard\",\"desc\":\"SAAS / FINANCE\",\"image\":\"/assets/portofolio/portfolio1.png\",\"span\":\"md:col-span-4\"},{\"title\":\"Mobile POS App\",\"desc\":\"RETAIL / ANDROID\",\"image\":\"/assets/portofolio/portfolio2.png\",\"span\":\"md:col-span-4\"},{\"title\":\"E-Commerce System\",\"desc\":\"SHOPPING / WEB\",\"image\":\"/assets/product/ischool.png\",\"span\":\"md:col-span-4\"},{\"title\":\"Corporate Website\",\"desc\":\"BRANDING / MODERN\",\"image\":\"/assets/product/isantri.png\",\"span\":\"md:col-span-7\"},{\"title\":\"Sistem Informasi Desa\",\"desc\":\"GOVERNMENT / WEB\",\"image\":\"/assets/product/pos.png\",\"span\":\"md:col-span-5\"}]','2026-06-04 08:22:11'),(50,'process_data','[{\"step\":\"01\",\"title\":\"Consultation\",\"desc\":\"Needs Analysis & Planning\",\"back_title\":\"DETAIL CONSULTATION\",\"detail\":\"Kami memulai dengan mendalami visi bisnis Anda. Sesi brainstorming intensif untuk menentukan fitur utama, target pasar, dan strategi teknologi yang paling efektif untuk mencapai tujuan Anda.\"},{\"step\":\"02\",\"title\":\"Desain UI/UX\",\"desc\":\"Wireframing & Prototyping\",\"back_title\":\"DETAIL DESAIN UI/UX\",\"detail\":\"Fokus pada pengalaman pengguna yang intuitif dan estetika modern. Kami membuat purwarupa interaktif sehingga Anda dapat merasakan alur navigasi aplikasi sebelum proses coding dimulai.\"},{\"step\":\"03\",\"title\":\"Development\",\"desc\":\"Coding & System Testing\",\"back_title\":\"DETAIL DEVELOPMENT\",\"detail\":\"Tim engineer kami membangun sistem menggunakan teknologi terkini yang skalabel. Kami menerapkan standar keamanan tinggi dan pengujian menyeluruh (QA) untuk memastikan performa yang stabil.\"},{\"step\":\"04\",\"title\":\"Launching\",\"desc\":\"Deployment & Maintenance\",\"back_title\":\"DETAIL LAUNCHING\",\"detail\":\"Membantu proses rilis ke App Store/Play Store atau hosting cloud. Kami tidak berhenti di sana; kami menyediakan dukungan teknis berkelanjutan dan pemeliharaan untuk menjaga sistem tetap prima.\"}]','2026-06-04 07:46:45'),(51,'pricing_title','Paket Layanan Kami','2026-06-04 07:46:45'),(52,'pricing_subtitle','Pilih paket yang sesuai dengan skala bisnis dan kebutuhan Anda','2026-06-04 07:46:45'),(53,'pricing_data','[{\"name\":\"Basic Package\",\"price\":\"Rp 2.000.000\",\"period\":\"one-time\",\"description\":\"For SMEs & landing pages\",\"features\":\"Max 5 Pages, Form & WA Button, 1 Month Maintenance, Basic SEO, Duration: 4-7 Days\",\"isPopular\":false,\"buttonText\":\"Pilih Paket\"},{\"name\":\"Professional Package\",\"price\":\"Rp 4.500.000\",\"period\":\"one-time\",\"description\":\"Exclusive custom design\",\"features\":\"Max 10 Pages, Custom Branding Design, CMS & Blog, Advanced SEO Optimization, Duration: 10-14 Days\",\"isPopular\":true,\"buttonText\":\"Pilih Paket\"},{\"name\":\"Premium Package\",\"price\":\"Rp 8.500.000\",\"period\":\"one-time\",\"description\":\"E-commerce & Custom Systems\",\"features\":\"Dynamic Web / E-Commerce, Catalog & Cart, Payment Gateway, Membership / Account, 3 Months Maintenance\",\"isPopular\":false,\"buttonText\":\"Pilih Paket\"}]','2026-06-04 07:46:45'),(54,'faq_data','[{\"question\":\"Berapa lama proses pembuatan satu website?\",\"answer\":\"Waktu pengerjaan bervariasi tergantung paket. Paket Basic memakan waktu 4-7 hari, sedangkan Paket Profesional dan Premium berkisar antara 10-14 hari kerja.\"},{\"question\":\"Apakah harga sudah termasuk hosting dan domain?\",\"answer\":\"Ya, untuk tahun pertama kami memberikan gratis Hosting Cloud kecepatan tinggi dan Domain (.com/.id/.net) untuk setiap paket yang Anda pilih.\"},{\"question\":\"Apakah website yang dibuat bisa saya edit sendiri?\",\"answer\":\"Tentu. Kami menggunakan sistem CMS (Content Management System) yang memudahkan Anda untuk mengubah teks, gambar, atau menambahkan artikel blog tanpa harus mengerti bahasa pemrograman.\"},{\"question\":\"Bagaimana dengan sistem keamanannya?\",\"answer\":\"Setiap website yang kami bangun dilengkapi dengan sertifikat SSL (HTTPS) gratis dan sistem keamanan standar industri untuk melindungi data Anda dan pengunjung.\"},{\"question\":\"Siapa pemilik konten yang saya buat?\",\"answer\":\"Seluruh konten dan data yang ada pada website atau aplikasi Anda sepenuhnya adalah milik Anda. Kami hanya membantu dalam proses pengembangan dan pemeliharaan sistem.\"}]','2026-06-04 07:46:45'),(55,'cta_title','Siap Membangun Sistem Digital?\nKonsultasikan Sekarang Juga!','2026-06-04 07:46:45'),(56,'cta_button','Hubungi WhatsApp','2026-06-04 07:46:45'),(57,'cta_link','','2026-06-04 07:46:45'),(58,'cta_phone','085188009152','2026-06-04 07:46:45'),(59,'cta_note','Konsultasi GRATIS','2026-06-04 07:46:45'),(60,'footer_address','Mitra terpercaya untuk inovasi digital bisnis Anda. Membantu dari ide hingga menjadi produk siap rilis.','2026-06-04 07:46:45'),(61,'footer_phone','085188009152','2026-06-04 07:46:45'),(62,'footer_email','info@garudanexa.co.id','2026-06-04 07:46:45'),(63,'footer_whatsapp','6285188009152','2026-06-04 07:46:45'),(64,'footer_instagram','#','2026-06-04 07:46:45'),(65,'footer_facebook','#','2026-06-04 07:46:45'),(66,'footer_linkedin','#','2026-06-04 07:46:45'),(67,'footer_tiktok','#','2026-06-04 07:46:45'),(68,'footer_youtube','#','2026-06-04 07:46:45'),(69,'footer_copyright','© 2026 PT. Garuda Nexa Bahtera. Semua hak dilindungi.','2026-06-04 07:46:45'),(307,'disabled_sections','[\"pricing\"]','2026-06-04 09:12:38');
